import{_ as e,c as i,o as r,a0 as t}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"fr/blog/inner-critic.md","filePath":"fr/blog/inner-critic.md"}');const n=e({name:"fr/blog/inner-critic.md"},[["render",function(e,a,n,o,s,u){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="comprendre-le-critique-interieur" tabindex="-1">Comprendre le critique intérieur <a class="header-anchor" href="#comprendre-le-critique-interieur" aria-label="Permalink to &quot;Comprendre le critique intérieur&quot;">​</a></h1><p>Tout joueur de pétanque connaît cette voix. Celle qui murmure « tu vas rater » juste avant de lancer. Celle qui repasse en boucle votre dernier coup raté. C&#39;est votre critique intérieure, et apprendre à la maîtriser est essentiel pour atteindre l&#39;excellence.</p><h2 id="qu-39-est-ce-que-le-critique-interieur" tabindex="-1">Qu&#39;est-ce que le critique intérieur ? <a class="header-anchor" href="#qu-39-est-ce-que-le-critique-interieur" aria-label="Permalink to &quot;Qu&amp;#39;est-ce que le critique intérieur ?&quot;">​</a></h2><p>La voix intérieure critique est cette voix qui juge, critique et mine votre confiance. À la pétanque, elle se manifeste souvent aux pires moments :</p><ul><li><strong>Avant un tir crucial</strong> : « Tout le monde regarde. Ne rate pas ça. »</li><li><strong>Après un échec</strong> : « Tu craques toujours sous la pression. »</li><li><strong>Pendant une série de défaites</strong> : « Tu n&#39;es pas assez bon pour ce niveau. »</li></ul><p>Cette voix ne cherche pas à vous nuire ; il s’agit en réalité d’une tentative de protection malavisée. Votre cerveau essaie de vous préparer à l’échec pour qu’il soit moins douloureux. Mais cette « protection » se transforme en autosabotage.</p><h2 id="identifier-vos-schemas" tabindex="-1">Identifier vos schémas <a class="header-anchor" href="#identifier-vos-schemas" aria-label="Permalink to &quot;Identifier vos schémas&quot;">​</a></h2><p>La première étape est la prise de conscience. Commencez par remarquer quand votre critique intérieure se manifeste :</p><h3 id="declencheurs-courants" tabindex="-1">Déclencheurs courants <a class="header-anchor" href="#declencheurs-courants" aria-label="Permalink to &quot;Déclencheurs courants&quot;">​</a></h3><ul><li>Situations de haute pression (balle de match, tournois importants)</li><li>Après avoir commis une erreur</li><li>Lorsque les adversaires performent bien</li><li>Quand les coéquipiers semblent frustrés</li><li>fatigue ou inconfort physique</li></ul><h3 id="messages-courants" tabindex="-1">Messages courants <a class="header-anchor" href="#messages-courants" aria-label="Permalink to &quot;Messages courants&quot;">​</a></h3><ul><li>« Tu ne supportes pas la pression »</li><li>« Tu n&#39;es pas aussi bon qu&#39;eux. »</li><li>« Tout le monde te juge »</li><li>« Tu échoues toujours quand c&#39;est important. »</li></ul><h2 id="l-39-impact-sur-la-performance" tabindex="-1">L&#39;impact sur la performance <a class="header-anchor" href="#l-39-impact-sur-la-performance" aria-label="Permalink to &quot;L&amp;#39;impact sur la performance&quot;">​</a></h2><p>Lorsque la voix critique intérieure prend le dessus, votre corps réagit :</p><ol><li><strong>La tension musculaire augmente</strong> — Votre lancer devient rigide</li><li><strong>La respiration devient superficielle</strong> — Moins d&#39;oxygène, moins de concentration</li><li><strong>La vision se rétrécit</strong> — Vous perdez conscience du terrain</li><li><strong>La prise de décision est compromise</strong> — Vous doutez de vous-même</li></ol><p>Cela crée un cercle vicieux : la critique intérieure engendre de mauvaises performances, ce qui donne encore plus de munitions à cette critique.</p><h2 id="strategies-pour-gerer-sa-voix-critique-interieure" tabindex="-1">Stratégies pour gérer sa voix critique intérieure <a class="header-anchor" href="#strategies-pour-gerer-sa-voix-critique-interieure" aria-label="Permalink to &quot;Stratégies pour gérer sa voix critique intérieure&quot;">​</a></h2><h3 id="_1-nommez-le-pour-l-39-apprivoiser" tabindex="-1">1. Nommez-le pour l&#39;apprivoiser <a class="header-anchor" href="#_1-nommez-le-pour-l-39-apprivoiser" aria-label="Permalink to &quot;1. Nommez-le pour l&amp;#39;apprivoiser&quot;">​</a></h3><p>Donnez un nom à votre critique intérieure – quelque chose d&#39;un peu ridicule. « Oh, revoilà Negative Nils ! » Cela crée une distance entre vous et cette voix, ce qui vous permet de l&#39;ignorer plus facilement.</p><h3 id="_2-remettre-en-question-les-preuves" tabindex="-1">2. Remettre en question les preuves <a class="header-anchor" href="#_2-remettre-en-question-les-preuves" aria-label="Permalink to &quot;2. Remettre en question les preuves&quot;">​</a></h3><p>Quand un critique vous dit « tu rates toujours tes coups sous pression », demandez-vous : est-ce vraiment vrai ? Pouvez-vous citer des moments où vous avez bien performé sous pression ? Le critique s’appuie sur des affirmations absolues qui reflètent rarement la réalité.</p><h3 id="_3-reformuler-le-message" tabindex="-1">3. Reformuler le message <a class="header-anchor" href="#_3-reformuler-le-message" aria-label="Permalink to &quot;3. Reformuler le message&quot;">​</a></h3><p>Transformer la critique en coaching :</p><ul><li>« Tu vas rater quelque chose » → « Concentre-toi sur ta routine »</li><li>&quot;Tout le monde vous regarde&quot; → &quot;C&#39;est votre moment de briller&quot;</li><li>&quot;Tu perds toujours tes moyens&quot; → &quot;Tu as déjà su gérer la pression&quot;</li></ul><h3 id="_4-utilisez-votre-routine-d-39-avant-tir" tabindex="-1">4. Utilisez votre routine d&#39;avant-tir <a class="header-anchor" href="#_4-utilisez-votre-routine-d-39-avant-tir" aria-label="Permalink to &quot;4. Utilisez votre routine d&amp;#39;avant-tir&quot;">​</a></h3><p>Une bonne routine de préparation mentale donne à votre esprit quelque chose de constructif sur lequel se concentrer, laissant moins de place à la critique.</p><h3 id="_5-pratiquez-l-39-autocompassion" tabindex="-1">5. Pratiquez l&#39;autocompassion <a class="header-anchor" href="#_5-pratiquez-l-39-autocompassion" aria-label="Permalink to &quot;5. Pratiquez l&amp;#39;autocompassion&quot;">​</a></h3><p>Traitez-vous comme vous traiteriez un coéquipier. Diriez-vous à un coéquipier en difficulté « tu es nul » ? Bien sûr que non. Faites preuve de la même bienveillance envers vous-même.</p><h2 id="developper-une-voix-interieure-bienveillante" tabindex="-1">Développer une voix intérieure bienveillante <a class="header-anchor" href="#developper-une-voix-interieure-bienveillante" aria-label="Permalink to &quot;Développer une voix intérieure bienveillante&quot;">​</a></h2><p>L’objectif n’est pas de faire taire complètement la voix critique intérieure — c’est quasiment impossible. Il s’agit plutôt de développer une voix plus constructive :</p><h3 id="la-voix-du-soutien-dit" tabindex="-1">La voix du soutien dit : <a class="header-anchor" href="#la-voix-du-soutien-dit" aria-label="Permalink to &quot;La voix du soutien dit :&quot;">​</a></h3><ul><li>&quot;Un lancer à la fois&quot;</li><li>«Faites confiance à votre formation»</li><li>«Vous avez déjà fait ça»</li><li>« Restez dans le présent »</li><li>&quot;Respirez et réinitialisez-vous&quot;</li></ul><h3 id="pratique-quotidienne" tabindex="-1">Pratique quotidienne <a class="header-anchor" href="#pratique-quotidienne" aria-label="Permalink to &quot;Pratique quotidienne&quot;">​</a></h3><p>Consacrez 5 minutes par jour :</p><ol><li>Repensez à un moment où vous avez bien performé.</li><li>Souvenez-vous de ce que vous ressentiez dans votre corps.</li><li>Écoutez ce que disait votre voix encourageante</li><li>Ancrez cette sensation par un geste physique (toucher votre boule, ajuster votre position).</li></ol><h2 id="en-competition" tabindex="-1">En compétition <a class="header-anchor" href="#en-competition" aria-label="Permalink to &quot;En compétition&quot;">​</a></h2><p>Quand la voix intérieure critique se manifeste pendant un match :</p><ol><li><strong>Reconnaissez-le</strong> : « Je remarque que je suis autocritique. »</li><li><strong>Respirez</strong> : Respirez lentement et profondément pour vous ressourcer.</li><li><strong>Utilisez votre point d&#39;ancrage</strong> : Le geste physique issu de votre pratique</li><li><strong>Retour à la routine</strong> : Concentrez-vous sur votre préparation avant la prise de vue</li></ol><h2 id="le-voyage-a-long-terme" tabindex="-1">Le voyage à long terme <a class="header-anchor" href="#le-voyage-a-long-terme" aria-label="Permalink to &quot;Le voyage à long terme&quot;">​</a></h2><p>Gérer sa voix intérieure critique n&#39;est pas une solution miracle. C&#39;est un travail de longue haleine qui s&#39;améliore avec le temps. Les athlètes de haut niveau n&#39;éliminent pas le doute ; ils apprennent à performer malgré lui.</p><p>Votre critique intérieure fera toujours partie de vous. Mais avec la pratique, sa voix s&#39;apaise et votre voix bienveillante se renforce. C&#39;est cet avantage mental qui distingue les bons joueurs des grands champions.</p><hr><p>| <em>En lien avec : <a href="/en/education/mental-strength/handling-pressure">Gérer la pression</a> | <a href="/en/education/mental-strength/pre-shot-routine">Routine de préparation au tir</a> | <a href="/en/education/mindfulness/techniques">Techniques de pleine conscience</a></em> |</p>',43)])])}]]);export{a as __pageData,n as default};
